91	+import { all } from '../db/index.js';
92	+import type { Book } from './book.js';
93	+import type { ReviewWithDetails } from './review.js';
94	+
95	+export interface RatedBook extends Book {
96	+  avg_rating: number;
97	+  review_count: number;
98	+}
99	+
100	+const BOOK_SORT_COLUMNS: Record<string, string> = {
101	+  title: 'title',
102	+  author: 'author',
103	+  year: 'published_year',
104	+};
105	+
106	+// Books with at least `minReviews` reviews, best average first.
107	+export function getTopRatedBooks(limit: number, minReviews: number): RatedBook[] {
108	+  return all(`
109	+    SELECT b.*, AVG(r.rating) AS avg_rating, COUNT(r.id) AS review_count
110	+    FROM books b
111	+    JOIN reviews r ON r.book_id = b.id
112	+    GROUP BY b.id
113	+    HAVING COUNT(r.id) >= ?
114	+    ORDER BY avg_rating DESC, b.title
115	+    LIMIT ?
116	+  `, [minReviews, limit]) as unknown as RatedBook[];
117	+}
118	+
119	+// Paginated catalogue. `page` starts at 1.
120	+export function getBooksPage(page: number, pageSize: number, sortKey = 'title'): Book[] {
121	+  const column = Object.hasOwn(BOOK_SORT_COLUMNS, sortKey) ? BOOK_SORT_COLUMNS[sortKey] : 'title';
122	+  return all(
123	+    `SELECT * FROM books ORDER BY ${column}, id LIMIT ? OFFSET ?`,
124	+    [pageSize, (page - 1) * pageSize]
125	+  ) as unknown as Book[];
126	+}
127	+
128	+const REVIEW_SORTS: Record<string, string> = {
129	+  newest: 'r.created_at DESC',
130	+  oldest: 'r.created_at ASC',
131	+  rating: 'r.rating DESC, r.created_at DESC',
132	+};
133	+
134	+// Reviews for a book in one of the whitelisted orders.
135	+export function getReviewsSorted(bookId: number, sortKey: string): ReviewWithDetails[] {
136	+  const sort = Object.hasOwn(REVIEW_SORTS, sortKey) ? REVIEW_SORTS[sortKey] : REVIEW_SORTS.newest;
137	+  return all(`
138	+    SELECT r.*, u.username, u.display_name, b.title as book_title, b.author as book_author
139	+    FROM reviews r
140	+    JOIN users u ON r.user_id = u.id
141	+    JOIN books b ON r.book_id = b.id
142	+    WHERE r.book_id = ?
143	+    ORDER BY ${sort}
144	+  `, [bookId]) as unknown as ReviewWithDetails[];
145	+}
146	+
147	+// Count of reviews per star value, always returning all five buckets.
148	+export function getRatingHistogram(bookId: number): Record<number, number> {
149	+  const rows = all(
150	+    'SELECT rating, COUNT(*) AS n FROM reviews WHERE book_id = ? GROUP BY rating',
151	+    [bookId]
152	+  ) as unknown as { rating: number; n: number }[];
153	+  const histogram: Record<number, number> = {};
154	+  for (let star = 1; star <= 5; star++) histogram[star] = 0;
155	+  for (const row of rows) histogram[row.rating] = row.n;
156	+  return histogram;
157	+}
