66	export function updateReview(id: number, data: { rating?: number; reviewText?: string }): Review | undefined {
67	  const existing = getReviewById(id);
68	  if (!existing) return undefined;
69	
70	  const updates: string[] = [];
71	  const values: unknown[] = [];
72	
73	  if (data.rating !== undefined) {
74	    updates.push('rating = ?');
75	    values.push(data.rating);
76	  }
77	  if (data.reviewText !== undefined) {
78	    updates.push('review_text = ?');
79	    values.push(data.reviewText);
80	  }
81	
82	  if (updates.length === 0) return existing;
83	
84	  values.push(id);
85	  run(`UPDATE reviews SET ${updates.join(', ')} WHERE id = ?`, values);
86	  return getReviewById(id);
87	}
